/* test_vectors.c — the frozen corpus (the vectors/ TSV files) against one C core.
 *
 *   test_vectors-<variant> <vectors-dir>
 *
 * Linked once per core (build/test_vectors-speed, -memory, ...), so each
 * binary proves exactly the object a consumer would link. The corpus is
 * generated by tools/vectorgen.py from the oracle, whose algorithm neither
 * core uses; see docs/contract.md "Vectors" for the schema.
 *
 * Absent vectors/ (a vendored copy of native/ without the repo around it) is a
 * SKIP, unless BRD14_REQUIRE_VECTORS=1, where it is a FAIL: the root Makefile
 * and CI set it so a broken path can never pass silently.
 *
 * valid.tsv          encode(ns, snow) == id, decode(id) == (ns, snow),
 *                    hash32(snow), unix_ms(snow). The ts/node/seq columns
 *                    are not checked: this ABI has no field reader.
 * invalid.tsv        decode(bytes) refuses with the listed class, and leaves
 *                    its outputs untouched.
 * encode_invalid.tsv encode refusals, including namespaces whose length is
 *                    not 3, refused at the caller level as NAMESPACE (the
 *                    fixed-width ABI cannot see a length; support.h).
 */
#include "branded_id.h"
#include "support.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#ifndef VARIANT
#define VARIANT "unknown"
#endif

#define MAX_FIELDS 8
#define REPORT_LIMIT 20

static unsigned long failures, checks;

static void fail(const char *file, unsigned long line, const char *what, const char *detail) {
  failures++;
  if (failures <= REPORT_LIMIT)
    fprintf(stderr, "FAIL c-%s %s:%lu: %s%s%s\n", VARIANT, file, line, what,
            detail ? ": " : "", detail ? detail : "");
}

static void check(int ok, const char *file, unsigned long line, const char *what) {
  checks++;
  if (!ok) fail(file, line, what, NULL);
}

static int class_of(const char *s, size_t n, branded_status *out) {
  for (unsigned i = 1; i < 5; i++) {
    if (strlen(brd_class[i]) == n && memcmp(brd_class[i], s, n) == 0) {
      *out = (branded_status)i;
      return 1;
    }
  }
  return 0;
}

/* Splits a TAB-separated line in place; returns the field count. */
static size_t split(char *line, char *field[], size_t len[], size_t max) {
  size_t n = 0;
  char *p = line;
  for (;;) {
    char *tab = strchr(p, '\t');
    if (n < max) {
      field[n] = p;
      len[n] = tab ? (size_t)(tab - p) : strlen(p);
    }
    n++;
    if (!tab) break;
    p = tab + 1;
  }
  return n;
}

typedef void (*row_fn)(const char *file, unsigned long line, char *field[], size_t len[],
                       size_t nfields);

/* Reads one TSV, skipping comments and blank lines. Returns the data-row
 * count, or -1 when the file cannot be opened. */
static long each_row(const char *dir, const char *name, row_fn fn) {
  char path[4096];
  if (snprintf(path, sizeof path, "%s/%s", dir, name) >= (int)sizeof path) return -1;
  FILE *f = fopen(path, "rb");
  if (!f) return -1;
  char buf[8192];
  unsigned long lineno = 0;
  long rows = 0;
  while (fgets(buf, sizeof buf, f)) {
    lineno++;
    size_t n = strlen(buf);
    if (n && buf[n - 1] == '\n') buf[--n] = '\0';
    else if (!feof(f)) {
      fail(name, lineno, "line too long", NULL);
      break;
    }
    if (n && buf[n - 1] == '\r') buf[--n] = '\0'; /* tolerate a CRLF checkout */
    if (n == 0 || buf[0] == '#') continue;
    char *field[MAX_FIELDS];
    size_t len[MAX_FIELDS];
    size_t nf = split(buf, field, len, MAX_FIELDS);
    fn(name, lineno, field, len, nf);
    rows++;
  }
  fclose(f);
  return rows;
}

static void valid_row(const char *file, unsigned long line, char *f[], size_t len[], size_t nf) {
  uint64_t snow, hash, ums;
  if (nf != 8 || len[0] != 3 || len[2] != BRANDED_LEN || !brd_parse_u64(f[1], len[1], &snow) ||
      !brd_parse_u64(f[3], len[3], &hash) || !brd_parse_u64(f[4], len[4], &ums)) {
    fail(file, line, "malformed row", NULL);
    return;
  }
  char out[BRANDED_LEN];
  branded_status s = branded_encode(f[0], snow, out);
  check(s == BRANDED_OK && memcmp(out, f[2], BRANDED_LEN) == 0, file, line, "encode(ns, snow) == id");

  char ns[BRANDED_NS_LEN];
  uint64_t got = 0;
  s = branded_decode(f[2], BRANDED_LEN, ns, &got);
  check(s == BRANDED_OK && memcmp(ns, f[0], 3) == 0 && got == snow, file, line,
        "decode(id) == (ns, snow)");
  check(branded_hash32(snow) == hash, file, line, "hash32(snow)");
  check(branded_unix_ms(snow) == ums, file, line, "unix_ms(snow)");
}

static void invalid_row(const char *file, unsigned long line, char *f[], size_t len[], size_t nf) {
  unsigned char id[64];
  branded_status want;
  long n = nf == 2 ? brd_unhex(f[0], len[0], id, sizeof id) : -1;
  if (n < 0 || !class_of(f[1], len[1], &want)) {
    fail(file, line, "malformed row", NULL);
    return;
  }
  char ns[BRANDED_NS_LEN] = {'#', '#', '#'};
  uint64_t snow = 0xDEADBEEFDEADBEEFULL;
  branded_status s = branded_decode((const char *)id, (size_t)n, ns, &snow);
  checks++;
  if (s != want) fail(file, line, "decode class", brd_class_name(s));
  check(memcmp(ns, "###", 3) == 0 && snow == 0xDEADBEEFDEADBEEFULL, file, line,
        "refused decode leaves its outputs untouched");
}

static branded_status encode_abi(const char *ns, uint64_t snow, char *out) {
  return branded_encode(ns, snow, out);
}

static void encode_invalid_row(const char *file, unsigned long line, char *f[], size_t len[],
                               size_t nf) {
  unsigned char ns[64];
  uint64_t snow;
  branded_status want;
  long n = nf == 3 ? brd_unhex(f[0], len[0], ns, sizeof ns) : -1;
  if (n < 0 || !brd_parse_u64(f[1], len[1], &snow) || !class_of(f[2], len[2], &want)) {
    fail(file, line, "malformed row", NULL);
    return;
  }
  char out[BRANDED_LEN];
  memset(out, '#', sizeof out);
  branded_status s = brd_encode_bytes(encode_abi, ns, (size_t)n, snow, out);
  checks++;
  if (s != want) fail(file, line, "encode class", brd_class_name(s));
  check(memcmp(out, "##############", BRANDED_LEN) == 0, file, line,
        "refused encode leaves its output untouched");
}

int main(int argc, char **argv) {
  const char *dir = argc > 1 ? argv[1] : "../../vectors";
  const char *req = getenv("BRD14_REQUIRE_VECTORS");
  int require = req && strcmp(req, "1") == 0;

  long valid = each_row(dir, "valid.tsv", valid_row);
  if (valid < 0) {
    if (require) {
      fprintf(stderr, "FAIL c-%s: %s/valid.tsv not found and BRD14_REQUIRE_VECTORS=1\n", VARIANT, dir);
      return 1;
    }
    printf("SKIP c-%s vectors: %s not present (set BRD14_REQUIRE_VECTORS=1 to require)\n", VARIANT, dir);
    return 0;
  }
  long invalid = each_row(dir, "invalid.tsv", invalid_row);
  long enc_invalid = each_row(dir, "encode_invalid.tsv", encode_invalid_row);
  if (invalid < 0 || enc_invalid < 0) {
    fprintf(stderr, "FAIL c-%s: %s is incomplete (invalid.tsv / encode_invalid.tsv)\n", VARIANT, dir);
    return 1;
  }
  if (valid == 0 || invalid == 0 || enc_invalid == 0) fail(dir, 0, "empty vector file", NULL);

  printf("%s c-%s vectors: valid %ld rows, invalid %ld, encode_invalid %ld; %lu checks, %lu failures\n",
         failures ? "FAIL" : "ok  ", VARIANT, valid, invalid, enc_invalid, checks, failures);
  return failures ? 1 : 0;
}
